module top_module(input clk, rst, en, output reg [3:0] count);always @(posedge clk or negedge rst) begin
    if (~rst) begin
      count <= 4'b0;
    end
    else if (en) begin
      count <= count + 1;
    end
  end

  assign carry_out = (count == 4'hF);

  assign carry_in = en;

