reg [15:0] FIFO[127:0];
reg [ 6:0] wr_ptr;
reg [ 6:0] rd_ptr;

assign  data_out = FIFO[rd_ptr];

always @(posedge clk)
begin
   if (rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
