module top_module(
  input clk, // clock signal
  input dir, // direction signal (0 for clockwise, 1 for counter-clockwise)
  input [6:0] spd, // speed signal (0 to 100)
  output reg pwm // pulse width modulated signal that controls the motor, changed to reg
);reg [6:0] duty_cycle; // variable duty cycle determined by spd input signal
  reg [6:0] counter; // counter for generating square wave
  reg direction; // direction of the motor

  always @ (posedge clk) begin
    // update duty cycle based on spd input signal
    duty_cycle <= spd;

    // update direction of the motor based on dir input signal
    direction <= dir;

    // increment counter and generate square wave
    counter <= counter + 1;

    if (counter <= duty_cycle) begin
      pwm <= 1;
    end else begin
      pwm <= 0;
    end
  end

  // H-bridge for controlling direction of motor
  always @ (posedge clk) begin // Use clk for synchronous behavior
    if (direction == 0) begin
      // clockwise
      // No change necessary for pwm here since its already set in first block
    end else begin
      // counter-clockwise
      pwm <= ~pwm; // This should modify the generated pwm signal based on direction
    end
  end

endmodule

