module top_module (
        input clk,
        input reset,
        input start,
        input ready,
        input stop,
        output reg out);parameter INIT=0, LOAD=1, RUN=2, STOP=3;
	reg[1:0] state, next;

	always @(posedge clk)
		if (reset) state <= INIT;
		else state <= next;


	always_comb begin
		case (state)
			INIT: next = start ? LOAD : INIT;
			LOAD: next = ready ? RUN : LOAD;
			RUN: next = stop ? STOP : RUN;
			STOP: next = start ? LOAD : STOP;
			default: next = 'x;
		endcase
	end

	assign out = (state == RUN);

endmodule

