code:
module coffee_machine (
	input clk,
	input resetn,
	input start,
	output ready);

	parameter IDLE=0, BREWING=1, DONE=2;
	reg [1:0] state, next_state;
	reg [3:0] counter;

	always @(posedge clk) begin
		if (~resetn) state <= IDLE;
		else state <= next_state;
	end

	always @(posedge clk) begin
		if (state == BREWING) counter <= counter + 1;
		else counter <= 0;
	end

	always_comb begin
		case (state)
			IDLE: next_state = start ? BREWING : IDLE;
			BREWING: next_state = (counter == 4'd9) ? DONE : BREWING;
			DONE: next_state = IDLE;
			default: next_state = IDLE;
		endcase
	end

	assign ready = (state == DONE);
endmodule

