module top_module(
  input bit0, 
  input bit1, 
  output reg parity0, 
  output reg parity1
);reg state;

  always @(posedge bit0 or posedge bit1) begin
    if (bit0 == 1'b1 || bit1 == 1'b1) begin
      if (state == 1'b0 && bit1 == 1'b1) begin
        parity1 <= 1'b1;
        state <= 1'b1;
      end else if (state == 1'b1 && bit0 == 1'b1) begin
        parity0 <= 1'b1;
        state <= 1'b0;
      end
    end

    if (bit0 == 1'b1 && bit1 == 1'b1) begin
      if (state == 1'b0) begin
        parity0 <= 1'b1;
        state <= 1'b1;
      end else if (state == 1'b1) begin
        parity1 <= 1'b1;
        state <= 1'b0;
      end
    end

    if (bit0 == 1'b0 && bit1 == 1'b0) begin
      parity0 <= 1'b0;
      parity1 <= 1'b0;
    end
  end
endmodule

