module top_module(
	input clk0,
	input flagi,
	input clk1,
	output reg flago
);/* Convert the flag into a level change */
reg toggle;
always @(posedge clk0)
    toggle <= ~toggle;

/* Synchronize the level change to clk1 using a three-flip-flop synchronizer */
reg [2:0] sync;
initial sync = 3'b000;
always @(posedge clk1)
    sync <= {sync[1:0], toggle};

/* Recreate the flag from the level change into the clk1 domain */
assign flago = sync[2] ^ sync[1];

endmodule

