);parameter POS  = 2'b00;  		
parameter CTL  = 2'b01;  		
parameter DATA = 2'b10;  		
parameter DATB = 2'b11;  		


reg		[15:0] datla;		
reg		[15:0] datlb;		
reg		[15:0] shifta;		
reg		[15:0] shiftb;		
reg		[8:0] hstart;		
reg		armed;				
reg		load;				
reg		load_del;




