	if (reset) 
		armed <= 0;
	else if (aen && address==CTL) 
		armed <= 0;
	else if (aen && address==DATA) 
		armed <= 1;




always @(posedge clk)
	load <= armed && hpos[8:0]==hstart[8:0] ? 1'b1 : 1'b0;

always @(posedge clk)
	load_del <= load;




always @(posedge clk)
	if (aen && address==POS)
