module parking_gate_controller (
    input clk,
    input resetn,
    input car_detected,
    output reg gate_open,
    output reg gate_closed);

    parameter CLOSED = 0, OPENING = 1, OPEN = 2, CLOSING = 3;
    reg [1:0] state, next_state;

    always @(posedge clk) begin
        if (~resetn) state <= CLOSED;
        else state <= next_state;
    end

    always_comb begin
        case (state)
            CLOSED: next_state = car_detected ? OPENING : CLOSED;
            OPENING: next_state = OPEN;
            OPEN: next_state = car_detected ? OPEN : CLOSING;
            CLOSING: next_state = CLOSED;
            default: next_state = CLOSED;
        endcase
    end

    always @(state) begin
        case (state)
            CLOSED: begin
                gate_open = 0;
                gate_closed = 1;
            end
            OPEN: begin
                gate_open = 1;
                gate_closed = 0;
            end
            default: begin
                gate_open = 0;
                gate_closed = 0;
            end
        endcase
    end
endmodule

