    x = num;
    count = 0;
    sqrt = 0;            // Initialize sqrt
end

always @(*) begin
    temp = x_next;
    x_next = (x + (num / x)) >> 1;
    if (temp == x_next) begin
        count = count + 1;
    end
end

always @(posedge clk) begin
    if (count == 2) begin
        sqrt <= x_next[15:8];
    end
    x <= x_next;
end

endmodule

