description:
Design a clock prescaler that generates three distinct output frequency signals: 1 Hz, 5 Hz, and 200 Hz, based on a given input clock. The module utilizes a series of counters to keep track of clock cycles, resetting them upon reaching predefined values correspondingly (100 million for 1 Hz, 20 million for 5 Hz, and 500,000 for 200 Hz). Each output is controlled by a flag that signals when the respective counter reaches its threshold, effectively dividing the input clock frequency to produce the desired slower outputs.
module top_module(
    input clock,
    output out1hz, out5hz, out200hz    
    );

code:
module top_module(
    input clock,
    output out1hz, out5hz, out200hz    
    );reg [27:0] count1, count5, count200;
    reg flag1, flag5, flag200;

    always@(posedge clock)
    begin

        if(count1 == 100_000_000)
            count1 = 0; 
        else 
            count1 = count1 + 1;


        if(count5 == 20_000_000)
            count5 = 0;
        else
            count5 = count5 + 1;


        if(count200 == 500_000)
             count200 = 0;
        else 
            count200 = count200 + 1;
    end

    always@(count1 or count5 or count200)
    begin

        if(count1 == 100_000_000) flag1 = 1;
        else flag1 = 0;


        if(count5 == 20_000_000) flag5 = 1;
        else flag5 = 0;


        if(count200 == 500_000) flag200 = 1;
        else flag200 = 0;
    end


    assign out1hz = flag1;
    assign out5hz = flag5;
    assign out200hz = flag200;

endmodule

