module top_module(
    areset,
    inclk0,
    c0,
    locked);input      areset;
    input      inclk0;
    output     c0;
    output     locked;

    reg [31:0] counter;
    reg        locked_reg;
    wire       c0;
    reg        c0_reg; // Added a reg to drive the output
    reg        locked;  // Changed to reg since it needs to be updated

    assign c0 = c0_reg; // Drive output c0 from the reg c0_reg

    parameter FREQ_DIV = 10; // Define the division factor

    always @(posedge inclk0 or negedge areset) begin
        if (~areset) begin
            counter <= 0;
            locked_reg <= 0;
            c0_reg <= 0;
            locked <= 0;
        end else begin
            counter <= counter + 1;
            if (counter >= FREQ_DIV) begin // Changed from equality to >=
                counter <= 0;
                c0_reg <= ~c0_reg;
            end
            if (locked_reg) begin
                locked <= 1;
            end else if (c0_reg == 1 && ~locked_reg) begin
                locked_reg <= 1;
            end
        end
    end

endmodule

