module fsm (
	input clk,
	input reset,
	input k,
	input l,
	output reg v);

	parameter E=0, F=1, G1=2, G2=3, G3=4;
	reg [2:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= E;
		else state <= next;
	end

	always_comb begin
		case (state)
			E: next = k ? F : E;
			F: next = l ? G1 : G2;
			G1: next = l ? G2 : G3;
			G2: next = k ? F : E;
			G3: next = k ? F : E;
			default: next = 'x;
		endcase
	end

	assign v = (state == G1 && l);

endmodule

