module top_module(
    input [1:0] A,
    input [1:0] B,
    input CI,
    output [1:0] Sum,
    output COUT_N
);wire [2:0] temp_sum;
    wire [1:0] temp_carry;

    assign temp_sum = {1'b0, A} + {1'b0, B} + {1'b0, CI};
    assign temp_carry = {temp_sum[2], temp_sum[1]};

    assign COUT_N = temp_sum[2];
    assign Sum = (temp_sum[1:0] >= 2'b10) ? (temp_sum[1:0] - 2'b10) : temp_sum[1:0];

endmodule

module top_module (
  input in,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);
    // State encoding
localparam A = 2'b00;
localparam B = 2'b01;
localparam C = 2'b10;
localparam D = 2'b11;

always @(*) begin
    // Default output is 0, will update for specific states if needed
    out = 0;

    // State transition logic
    case(state)
        A: begin
            if (in == 1'b0)
                next_state = D;
            else
                next_state = A;
            out = 0;  // Output is 0 in state A
        end
        B: begin
            if (in == 1'b0)
                next_state = B;
            else
                next_state = B;
            out = 1;  // Output is 1 in state B
        end
        C: begin
            if (in == 1'b0)
                next_state = C;
            else
                next_state = B;
            out = 1;  // Output is 1 in state C
        end
        D: begin
            if (in == 1'b0)
                next_state = A;
            else
                next_state = C;
            out = 1;  // Output is 1 in state D
        end
        default: begin
            next_state = A;  // Default transition to state A if invalid state
            out = 0;
        end
    endcase
end

endmodule

