module simple_alu (
    input [7:0] A,
    input [7:0] B,
    input [2:0] ctrl,
    output reg [7:0] result
);

    always @(*) begin
        case (ctrl)
            3'b000: result = A + B;
            3'b001: result = A - B;
            3'b010: result = A & B;
            3'b011: result = A | B;
            3'b100: result = A ^ B;
            default: result = 8'b00000000;
        endcase
    end

endmodule

module top_module(
		input wire iClock,
		input wire iReset,
		output wire oOut64,
		output wire oOut128,
		output wire oOut256
	);reg [16:0] rOscCounter; // log2(4194304/256) = 14. Last bit corresponds to the output.

	always @ (posedge iClock) begin
		if (iReset) begin
			rOscCounter <= 0;
		end
		else begin
			rOscCounter <= rOscCounter+1;
		end
	end

	assign oOut64 = (rOscCounter == 64) ? 1'b1 : 1'b0;
	assign oOut128 = (rOscCounter == 128) ? 1'b1 : 1'b0;
	assign oOut256 = (rOscCounter == 256) ? 1'b1 : 1'b0;

endmodule

