wire 			g0,g1,p0,p1;
wire			p1g0;
wire 			c2;

and and_0(g0,in1[0],in2[0]);
and and_1(g1,in1[1],in2[1]);
xor xor_0(p0,in1[0],in2[0]);
xor xor_1(p1,in1[1],in2[1]);

and and_2(p1g0,p1,g0);
or  or_1 (c2,g1,p1g0);


