module top_module(
    input [3:0] data_in,
    output [2:0] data_out,
    output [1:0] parity
);wire [3:0] sum;
    assign sum = data_in + 4'hF;

    assign data_out = sum[2:0];

    wire [3:0] count_ones;
    assign count_ones = {sum[3], sum[2]} + {sum[1], sum[0]};

    assign parity = count_ones[1:0] % 2'b10;

endmodule

