always @(posedge CK, negedge S, negedge R)
begin
  if (S)
    Q <= 1;
  else if (R)
    Q <= 0;
  else if (J && K)
    Q <= ~Q;
  else if (J)
    Q <= 1;
  else if (K)
    Q <= 0;
end

assign QN = ~Q;

endmodule

module binary_subtractor(
	input      [3:0] A,
	input      [3:0] B,

	output reg [3:0] result,
	output reg borrow_out
);

always @(*) begin
