module decoder_3to8 (A, EN, Y);
input [2:0] A;
input EN;
output reg [7:0] Y;

always @(*) begin
    if (EN) begin
        case (A)
            3'b000: Y = 8'b00000001;
            3'b001: Y = 8'b00000010;
            3'b010: Y = 8'b00000100;
            3'b011: Y = 8'b00001000;
            3'b100: Y = 8'b00010000;
            3'b101: Y = 8'b00100000;
            3'b110: Y = 8'b01000000;
            3'b111: Y = 8'b10000000;
            default: Y = 8'b00000000;
        endcase
    end else begin
        Y = 8'b00000000;
    end
end

endmodule

module top_module(clk, addr, out, in, READ_EN, WRITE_EN);parameter WORD_SIZE = 16;

    input [WORD_SIZE-1:0] addr, in;
    input READ_EN, WRITE_EN, clk;
    output reg [WORD_SIZE-1:0] out;

    reg [WORD_SIZE-1:0] REG_FILE [0:4095];

    always  @(negedge clk) 
    begin
        if (WRITE_EN==1) begin
        REG_FILE[addr] <= in;

        end
        else if (READ_EN==1) begin
        out <= REG_FILE[addr];

        end
    end

endmodule

